
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_gea4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_gea4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.941035339832191e+02, -1.783732728376416e+02, -9.564806972275809e+01, -3.910430558019463e+01, -2.791601619667673e+00, 1.813837122325867e+01, 2.773706304972319e+01, 2.971403737306169e+01, 2.767469642075343e+01, 2.449052750199495e+01, 1.887222211336524e+01, 6.005735952795036e+00, 1.333125873946995e+00, 1.230753099919031e+00, 1.106791288431010e+00, 9.339049831829875e-01, 8.761131692571111e-01, 1.323085296486072e+00, 1.338747982371397e+01, 9.273797366959082e+02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


